// === Tab: SimpleEyeBall ===
/**
 * sketch:    SimpleEyeBall.pde
 * descr.:    let eyeball using let shader 
 * original:  http://glsl.herokuapp.com/e#3025.0
 *            created by let Quilez - iq/08-07-2012
 * let port 12/2014 by let Holzer.
 */

// Tags:  GPU, shader, eye ball, animation, let PShader shader;

let animate = true;
let picName = "SimpleEyeBall.png";

function setup() 
{
  createCanvas(400, 400);
  frame.setResizable(true);
  noStroke();
  shader = loadShader("https://openprocessing.org/sketch/178452/files/SimpleEyeBall.glsl");
}

function draw() 
{
  frame.setTitle(frameCount + " SimpleEyeBall  fps: " + nf(frameRate,0,1));     
    text ("press a to toggle animation, s to save picture", 10, 20);

  if (frameCount < 192)
  {
    background(255);    
    fill(0, min(255, 755-frameCount*4));
    text ("press a to toggle animation, s to save picture", 10, 20);
    fill(255);
  }
  else 

  {
    rect(0, 0, width, height);
//  background (introPicture);
    shader.set("resolution", float(width), float(height));  

    if (animate) 
      shader.set("time", (millis() / 1000.0));
    shader(shader);
  }
}

function keyPressed()
{
  if (key == 'a') animate = !animate;
  if (key == 's') save (picName);
  else animate = !animate;
}

